mapper.select:
SELECT v.vote_sq, v.vote_ttl, v.user_sq, u.user_nickname, v.vote_category_cd, v.vote_end_dt, v.vote_created_at_dtm, v.vote_view_cnt, v.vote_is_deleted_yn, (SELECT COUNT(*) FROM TBL_VOTE_OPTION_S o WHERE o.vote_sq = v.vote_sq) AS option_cnt, (SELECT COUNT(*) FROM TBL_VOTE_RECORD_S r WHERE r.vote_sq = v.vote_sq) AS total_vote_cnt FROM TBL_VOTE_M v LEFT JOIN TBL_USER_M u ON u.user_sq = v.user_sq WHERE 1 = 1
AND v.vote_ttl LIKE CONCAT('%', #{keyword}, '%')
AND v.vote_category_cd = #{category}
ORDER BY v.vote_created_at_dtm ASC, v.vote_sq ASC ORDER BY v.vote_view_cnt DESC, v.vote_sq DESC ORDER BY v.vote_created_at_dtm DESC, v.vote_sq DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM TBL_VOTE_M v WHERE 1 = 1
AND v.vote_ttl LIKE CONCAT('%', #{keyword}, '%')
AND v.vote_category_cd = #{category}

mapper.update:
UPDATE TBL_VOTE_M
SET vote_ttl = #{voteTtl},
    vote_description_edt = #{voteDescriptionEdt},
    vote_category_cd = #{voteCategoryCd},
    vote_end_dt = #{voteEndDt}
WHERE vote_sq = #{voteSq}
